/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic a,
    input  logic b,
    input  logic c,
    input  logic d,
    output logic out
);
    assign out = a "'^ b ''^ c ''^ d;
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic a, b, c, d;
    wire out;
    logic expected;
    integer row_index, column_index;
    integer vector_index, pass_index;
    integer checks = 0;
    logic map_values [0:3][0:3];
    TopModule dut (.a(a), .b(b), .c(c), .d(d), .out(out));

    function automatic integer gray_index(input logic [1:0] pair_value);
        case (pair_value)
            2'"'b00: gray_index = 0;
            2'b01: gray_index = 1;
            2'b11: gray_index = 2;
            2'b10: gray_index = 3;
            default: gray_index = 0;
        endcase
    endfunction

    initial begin
        map_values[0][0]=0; map_values[0][1]=1; map_values[0][2]=0; map_values[0][3]=1;
        map_values[1][0]=1; map_values[1][1]=0; map_values[1][2]=1; map_values[1][3]=0;
        map_values[2][0]=0; map_values[2][1]=1; map_values[2][2]=0; map_values[2][3]=1;
        map_values[3][0]=1; map_values[3][1]=0; map_values[3][2]=1; map_values[3][3]=0;
        for (pass_index=0; pass_index<2; pass_index=pass_index+1) begin
            for (vector_index=0; vector_index<16; vector_index=vector_index+1) begin
                if (pass_index == 0) {a,b,c,d} = 4'(vector_index);
                else {a,b,c,d} = 4'(15-vector_index);
                #1;
                row_index = gray_index({c,d});
                column_index = gray_index({a,b});
                expected = map_values[row_index][column_index];
                if (out "'!== expected)
                    $fatal(1, "FAIL abcd=%b%b%b%b expected=%b actual=%b", a,b,c,d,expected,out);
                checks = checks + 1;
            end
        end
        $display("PASS: %0d comparisons; all 16 binary combinations in both directions", checks);
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: development test timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > development_compile.log 2>&1
compile_status=$?
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > development_simulation.log 2>&1
    simulation_status=$?
else
    simulation_status=not_run
fi
python3 - "$compile_status" "$simulation_status" <<'"'PY'
import json,sys
from pathlib import Path
compile_ok=sys.argv[1]=='0'
sim_ok=sys.argv[2]=='0' and 'PASS: 32 comparisons' in Path('development_simulation.log').read_text() if Path('development_simulation.log').exists() else False
report={'revision_count':0,'contract_corrections':[], 'checks':[{'name':'frozen_contract_gate','result':'passed_structure_only','log':'contract_validation.log'},{'name':'static_rtl_review','result':'pass','details':'Exact TopModule ports, one-bit unsigned logic, continuous combinational assignment, no state, delays, latches or dependencies.'},{'name':'Icarus -g2012 -Wall explicit dev_tb elaboration','result':'pass' if compile_ok else 'fail','exit_code':int(sys.argv[1]),'timeout_seconds':20,'log':'development_compile.log'},{'name':'independent K-map exhaustive simulation','result':'pass' if sim_ok else 'fail_or_not_run','exit_code':sys.argv[2],'timeout_seconds':20,'log':'development_simulation.log','comparisons':32 if sim_ok else None}], 'development_outcome':'pass' if compile_ok and sim_ok else 'tools_failed_or_check_failed','limitations':['Binary-input behavior verified; X/Z behavior is unspecified by the problem.','No synthesis, board testing or official evaluation performed.'],'files':{'rtl':'candidate.sv','initial_rtl':'candidate_initial.sv','testbench':'dev_tb.sv','contract':'contract.json'}}
Path('worker_report.json').write_text(json.dumps(report,indent=2)+'\\n')
PY
cat development_compile.log development_simulation.log worker_report.json"

